func newTailCmd(flags *rootFlags) *cobra.Command {
	var resource string
	var interval time.Duration
	var follow bool

	cmd := &cobra.Command{
		Use:         "tail [resource]",
		Short:       "Stream live changes by polling the API at regular intervals",
		Annotations: map[string]string{"mcp:read-only": "true", "pp:no-error-path-probe": "true"},
		Long: `Tail streams live data changes by polling the API at configurable intervals.
Events are emitted as NDJSON to stdout for piping to other tools.
Gracefully shuts down on SIGTERM/SIGINT.

Note: For APIs with WebSocket or SSE support, a future version will use
native streaming instead of polling.`,
		Example: `  # Tail all changes every 10 seconds
  3cx-xapi-pp-cli tail --interval 10s

  # Tail a specific resource
  3cx-xapi-pp-cli tail messages --interval 5s

  # Pipe to jq for filtering
  3cx-xapi-pp-cli tail events --interval 30s | jq 'select(.type == "error")'`,
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) > 0 {
				resource = args[0]
			}
			// JSON help envelope: when called with no resource AND --json,
			// surface the list of known resources so agents can discover
			// what to pass without parsing a usage error message.
			// Envelope: {resources: [...], note}.
			if resource == "" && flags.asJSON {
				return printJSONFiltered(cmd.OutOrStdout(), map[string]any{
					"resources": tailKnownResources(),
					"note":      "tail requires a resource name; pass one of the listed names",
				}, flags)
			}
			if resource == "" {
				return fmt.Errorf("resource name required (e.g., 'tail messages')")
			}
			// Reject a resource this CLI does not expose before binding the poll
			// loop: an unknown name only ever 404s, so failing fast with a
			// non-zero exit (and the valid set) beats warning once per poll
			// forever. Also satisfies the invalid-argument contract the dogfood
			// error-path probe checks.
			knownResource := false
			for _, r := range tailKnownResources() {
				if r == resource {
					knownResource = true
					break
				}
			}
			if !knownResource {
				return fmt.Errorf("unknown resource %q; known resources: %v", resource, tailKnownResources())
			}

			c, err := flags.newClient()
			if err != nil {
				return err
			}
			c.NoCache = true
			if cliutil.IsDogfoodEnv() {
				follow = false
			}

			path := "/" + resource

			sig := make(chan os.Signal, 1)
			signal.Notify(sig, syscall.SIGTERM, syscall.SIGINT)

			enc := json.NewEncoder(os.Stdout)

			if follow {
				fmt.Fprintf(os.Stderr, "Tailing %s every %s (Ctrl+C to stop)\n", resource, interval)
			}

			// Initial fetch
			initialErr := fetchAndEmit(cmd.Context(), c, path, enc)
			if !follow {
				return initialTailResult(false, initialErr)
			}
			if initialErr != nil {
				fmt.Fprintf(os.Stderr, "warning: initial fetch failed: %v\n", initialErr)
			}

			ticker := time.NewTicker(interval)
			defer ticker.Stop()

			for {
				select {
				case <-sig:
					fmt.Fprintln(os.Stderr, "\nShutting down gracefully...")
					return nil
				case <-ticker.C:
					if err := fetchAndEmit(cmd.Context(), c, path, enc); err != nil {
						fmt.Fprintf(os.Stderr, "warning: poll failed: %v\n", err)
					}
				}
			}
		},
	}

	cmd.Flags().StringVar(&resource, "resource", "", "Resource type to tail")
	cmd.Flags().DurationVar(&interval, "interval", 10*time.Second, "Poll interval")
	cmd.Flags().BoolVar(&follow, "follow", true, "Keep running (set --follow=false for single poll)")

	return cmd
}

func initialTailResult(follow bool, fetchErr error) error {
	if !follow {
		return fetchErr
	}
	return nil
}

